"""Context-window budget for Mantle LLM requests.

The budget is a guardrail, not a target: a fully-populated v2 system prompt
measures roughly 1.5–3k tokens plus ~1k of history, so the 8k default gives
2–3x headroom for verbose agent configs while bounding voice-path latency,
per-turn cost, and pathological growth (huge catalogues, giant phase
instructions) before they surface as provider errors.

Enforcement trims the oldest conversation-history **turns** first (a new user
message starts a turn — including parallel multi-tool batches and multi-round
tool exchanges), so assistant ``tool_calls`` headers are never separated from
their ``tool`` results.  The system message and the protected current-turn
suffix are never dropped, and the system prompt itself is never truncated —
cutting instructions mid-sentence is worse than an over-budget prompt, so when
the next whole turn cannot be dropped without going below
``MIN_HISTORY_MESSAGES`` we only log (remaining history may stay above that
floor).
"""

from __future__ import annotations

from typing import Any, List, Mapping

import structlog

from rasa.mantle.prompts.messages import KEY_CONTENT, KEY_ROLE, LlmMessage
from rasa.shared.constants import ROLE_USER
from rasa.shared.utils.tiktoken_utils import resolve_tiktoken_encode

structlogger = structlog.get_logger()

DEFAULT_MAX_PROMPT_TOKENS = 8000
"""Default per-request prompt budget; override via ``max_prompt_tokens``."""

MAX_PROMPT_TOKENS_CONFIG_KEY = "max_prompt_tokens"
"""Knob on ``orchestrator`` in agent.yml."""

MIN_HISTORY_MESSAGES = 2
"""Minimum remaining history message count; whole-turn drops may stop above it."""

PROMPT_ONLY_LLM_CONFIG_KEYS = (MAX_PROMPT_TOKENS_CONFIG_KEY,)
"""LLM-config keys consumed by prompt construction; must be stripped before
the config reaches ``llm_factory`` / provider client construction."""

_TOKENS_PER_MESSAGE_OVERHEAD = 4
"""Approximate per-message wrapping overhead in OpenAI-style chat formats."""


def resolve_max_prompt_tokens(llm_config: Mapping[str, Any]) -> int:
    """Read the prompt token budget from the LLM config, with default."""
    raw_value = llm_config.get(MAX_PROMPT_TOKENS_CONFIG_KEY)
    if raw_value is None:
        return DEFAULT_MAX_PROMPT_TOKENS

    try:
        max_tokens = int(raw_value)
    except (TypeError, ValueError):
        max_tokens = 0

    if max_tokens <= 0:
        structlogger.warning(
            "mantle.prompts.invalid_max_prompt_tokens",
            configured_value=raw_value,
            default=DEFAULT_MAX_PROMPT_TOKENS,
        )
        return DEFAULT_MAX_PROMPT_TOKENS
    return max_tokens


def estimate_message_tokens(messages: List[LlmMessage], model_name: str) -> int:
    """Estimate the token footprint of a chat message list.

    Uses tiktoken with graceful fallback (unknown model → cl100k_base →
    whitespace split), plus a small per-message wrapping overhead.
    """
    encode = resolve_tiktoken_encode(model_name)
    return sum(
        len(encode(_content_text(message))) + _TOKENS_PER_MESSAGE_OVERHEAD
        for message in messages
    )


def trim_history_to_budget(
    messages: List[LlmMessage],
    max_tokens: int,
    model_name: str,
) -> List[LlmMessage]:
    """Drop the oldest conversation-history turns until within budget.

    Trimming is atomic at turn boundaries so an assistant ``tool_calls``
    header is never separated from its ``tool`` result messages.

    Two regions are always preserved:

    * the system prompt (``messages[0]``), and
    * the **protected suffix** — every message from the current user turn
      onward.  The suffix covers the user's request plus anything appended
      after it within the turn (the within-turn assistant tool-call / tool-
      result exchange, or a rephrase instruction), so those are never dropped
      and are always counted against the budget.

    Only the history band between the two is trimmed, oldest turn first.
    Trimming stops when dropping the next whole turn would leave fewer than
    ``MIN_HISTORY_MESSAGES`` history messages — so remaining history may stay
    **above** that floor when the oldest turn is larger than the slack under
    the floor (parallel multi-tool batches and multi-round tool exchanges are
    the same turn unit).  Never raises — if the prompt still exceeds the
    budget at that point, a warning is logged and the (reduced) messages are
    returned.
    """
    encode = resolve_tiktoken_encode(model_name)
    costs = [
        len(encode(_content_text(message))) + _TOKENS_PER_MESSAGE_OVERHEAD
        for message in messages
    ]
    if sum(costs) <= max_tokens:
        return messages

    suffix_start = _protected_suffix_start(messages)
    history = list(messages[1:suffix_start])
    history_costs = costs[1:suffix_start]
    fixed_tokens = costs[0] + sum(costs[suffix_start:])

    turns = _group_history_into_turns(history)
    turn_costs: List[int] = []
    cost_index = 0
    for turn in turns:
        turn_len = len(turn)
        turn_costs.append(sum(history_costs[cost_index : cost_index + turn_len]))
        cost_index += turn_len

    estimated_tokens = fixed_tokens + sum(turn_costs)
    history_len = len(history)
    removed_count = 0
    while estimated_tokens > max_tokens and turns:
        oldest_len = len(turns[0])
        if history_len - oldest_len < MIN_HISTORY_MESSAGES:
            break
        turns.pop(0)
        estimated_tokens -= turn_costs.pop(0)
        removed_count += oldest_len
        history_len -= oldest_len

    history = [message for turn in turns for message in turn]

    if removed_count:
        structlogger.warning(
            "mantle.prompts.history_trimmed",
            removed_count=removed_count,
            estimated_tokens=estimated_tokens,
            max_tokens=max_tokens,
        )
    if estimated_tokens > max_tokens:
        structlogger.warning(
            "mantle.prompts.budget_exceeded",
            estimated_tokens=estimated_tokens,
            max_tokens=max_tokens,
            removed_count=removed_count,
        )
    return [messages[0], *history, *messages[suffix_start:]]


def _group_history_into_turns(history: List[LlmMessage]) -> List[List[LlmMessage]]:
    """Group trimmable history into turns for atomic dropping.

    A new ``user`` message starts a new turn.  Everything until the next user
    (text replies, a parallel multi-tool batch, or sequential tool rounds) is
    one turn.  A turn may begin without a user message (utterance-window
    snap-back can leave an assistant ``tool_calls`` group whose user line was
    trimmed); that leading group stays one unit until the next user message so
    tool-call/result pairs are never split.
    """
    turns: List[List[LlmMessage]] = []
    current: List[LlmMessage] = []
    for message in history:
        if message.get(KEY_ROLE) == ROLE_USER and current:
            turns.append(current)
            current = [message]
        else:
            current.append(message)
    if current:
        turns.append(current)
    return turns


def _protected_suffix_start(messages: List[LlmMessage]) -> int:
    """Index of the current user turn — the start of the protected suffix.

    Everything from here on (user request + any within-turn assistant
    tool-call / tool-result exchange or appended instruction) is never trimmed.
    When there is no user turn at all, the whole tail after the system prompt
    is protected (index ``1``) — never the system prompt itself — so the system
    message is not duplicated and a within-turn tool exchange is not dropped.
    """
    for index in range(len(messages) - 1, 0, -1):
        if messages[index].get(KEY_ROLE) == ROLE_USER:
            return index
    return 1


def _content_text(message: LlmMessage) -> str:
    """Message content as text; estimation must never crash the turn path.

    Assistant tool-call messages carry ``content=None``; treat that as empty
    (the tool-call payload itself is not counted here — a small, deliberate
    under-count for the rare over-budget tail).
    """
    content = message.get(KEY_CONTENT)
    if content is None:
        return ""
    return content if isinstance(content, str) else str(content)
